package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.ArrayUtils.add(T[] array, T element)
 */
public class ArrayUtils_add_TriageGen2Test {

    @Test
    public void testAdd_WithExistingArrayAndElement() {
        String[] input = {"a", "b"};
        String element = "c";
        String[] expected = {"a", "b", "c"};
        String[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
        assertNotSame(input, result); // Ensure a new array is returned
        assertEquals(3, result.length);
    }










}

